CREATE TABLE portfolios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name VARCHAR(100) NOT NULL, country VARCHAR(40) NOT NULL, currency VARCHAR(3) NOT NULL, asset_type VARCHAR(160), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE holdings (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, portfolio_id BIGINT NOT NULL REFERENCES portfolios(id) ON DELETE CASCADE, symbol VARCHAR(20) NOT NULL, instrument_name VARCHAR(160) NOT NULL, quantity DECIMAL(24,8) NOT NULL, average_cost DECIMAL(20,6) NOT NULL, market_value DECIMAL(20,6), currency VARCHAR(3) NOT NULL, UNIQUE(portfolio_id,symbol));
CREATE SEQUENCE watchlists_id_seq START WITH 1;
CREATE TABLE watchlists_usa (id BIGINT DEFAULT NEXT VALUE FOR watchlists_id_seq PRIMARY KEY, user_id BIGINT NOT NULL DEFAULT 1, name VARCHAR(40) NOT NULL, market VARCHAR(10) NOT NULL, currency VARCHAR(3) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE watchlists_india (id BIGINT DEFAULT NEXT VALUE FOR watchlists_id_seq PRIMARY KEY, name VARCHAR(40) NOT NULL, market VARCHAR(10) NOT NULL, currency VARCHAR(3) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE watchlist_items_usa (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, watchlist_id BIGINT NOT NULL REFERENCES watchlists_usa(id) ON DELETE CASCADE, symbol VARCHAR(15) NOT NULL, name VARCHAR(160) NOT NULL, is_favorite BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(watchlist_id,symbol));
CREATE TABLE watchlist_items_india (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, watchlist_id BIGINT NOT NULL REFERENCES watchlists_india(id) ON DELETE CASCADE, symbol VARCHAR(15) NOT NULL, name VARCHAR(160) NOT NULL, is_favorite BOOLEAN NOT NULL DEFAULT FALSE, UNIQUE(watchlist_id,symbol));
CREATE TABLE user_preferences (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, user_key VARCHAR(120) NOT NULL UNIQUE, favorite_watchlists TEXT NOT NULL, favorite_symbols TEXT NOT NULL, watchlist_columns TEXT NOT NULL);
